#include <bits/stdc++.h>
using namespace std;
#define int long long

void solve(){
    int n;
    cin>>n;
    
    vector<int> arr(3*n);
    
    
    for(int i=0; i<3*n; i++) cin>>arr[i];
    sort(arr.rbegin(),arr.rend());
    
    vector<int> pre(3*n+1);
    
    
    for(int i=1;i<=3*n;i++){
        pre[i] = arr[i-1]+ pre[i-1];
    }
    
    
    
    
    int ans = 0;
    
   for(int k = 0;k <= 2*n;k++){
       int low = max(0LL,k-n);
       int high =  k/2;
       
       if (low > high) continue;
       
       while(high - low > 2){
           int m1 = low + (high - low)/3;
           int m2 = high - (high - low)/3;
           
           int val1 = 2LL*pre[m1] + pre[2*k - 3*m1];
           int val2 = 2LL*pre[m2] + pre[2*k - 3*m2];
           
           if (val1 < val2){
               low = m1;
           }
           else if (val1 > val2){
               high = m2;
           }
           else{
               low = m1;
               high = m2;
           }
       }
       
       int best_aval = -1;
       
       for(int a_cnt = low;a_cnt <= high;a_cnt++){
           int curr = 2LL*pre[a_cnt] + pre[2*k - 3*a_cnt];
            
            if (curr > best_aval){
                best_aval = curr;
            }
       }
       
       int curr_total = best_aval + 3LL*pre[3*n - k];
       
       if (curr_total > ans){
           ans = curr_total;
       }
   }
   
   cout << ans << endl;
    
}

signed main() {
	// your code goes here
    int t;
    cin>>t;
    while(t--){
        solve();
    }
}
